head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
        txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());
        txb_ISU_NM.setValue(parentWin.txb_SearchIsuNm.getValue());
        await scwin.readSync();
        if (dts_Item.getRowCount() === 0) {
            dts_Item.insertRow();
            btn_save.setBackgroundImage("../img/btn_save.gif");
            btn_save.setDisabled(false);
            btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_Update.setDisabled(true);
        } else {
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            btn_save.setDisabled(true);
            btn_Update.setBackgroundImage("../img/btn_modify.gif");
            btn_Update.setDisabled(false);
        }
        edt_PF_TOT_FEE.focus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Update_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    try {
        $c.lc.fn_alertMsg('S');
        btn_save.setBackgroundImage("../img/btn_save_d.gif");
        btn_save.setDisabled(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09320.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name txa_PF_INVSTWARN_CONTN_onkillfocus
 * @description txa_PF_INVSTWARN_CONTN onkillfocus 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txa_PF_INVSTWARN_CONTN_onkillfocus = function() {
    try {
        edt_PF_TOT_FEE.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09320.txa_PF_INVSTWARN_CONTN_onkillfocus" });
    }
};

/**
 * @method
 * @name btn_calcul_onclick
 * @description 「계산」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_calcul_onclick = async function() {
    try {
        await scwin.calcul();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_calcul_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/pf/PfLstinvstg.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};

/**
 * @method
 * @name checkRt
 * @description 총보수,총비용관련 입력체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkRt = async function() {
    if (edt_CIS_COST_RT.getValue() === "") {
        await $c.win.alert("'집합투자업자보수'를 입력하세요.");
        edt_CIS_COST_RT.focus();
        return false;
    }
    if (edt_AP_CMP_LP_COST_RT.getValue() === "") {
        await $c.win.alert("'AP/LP보수'를 입력하세요.");
        edt_AP_CMP_LP_COST_RT.focus();
        return false;
    }
    if (edt_TRST_COM_COST_RT.getValue() === "") {
        await $c.win.alert("'신탁회사보수'를 입력하세요.");
        edt_TRST_COM_COST_RT.focus();
        return false;
    }
    if (edt_TRANSAGNT_COST_RT.getValue() === "") {
        await $c.win.alert("'일반사무관리회사보수'를 입력하세요.");
        edt_TRANSAGNT_COST_RT.focus();
        return false;
    }
    if (edt_MISC_COST_RT.getValue() === "") {
        await $c.win.alert("'기타비용'을 입력하세요.");
        edt_MISC_COST_RT.focus();
        return false;
    }
    if (edt_SYNTH_SWAP_COST_RT.getValue() === "") {
        await $c.win.alert("'스왑비용'을 입력하세요.");
        edt_SYNTH_SWAP_COST_RT.focus();
        return false;
    }
};

/**
 * @method
 * @name calcul
 * @description 총보수,총비용 계산
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcul = async function() {
    await scwin.checkRt();
    let pPF_TOT_FEE = 0;
    let pTOT_COST_RT = 0;
    pPF_TOT_FEE = parseFloat(edt_CIS_COST_RT.getValue()) + parseFloat(edt_AP_CMP_LP_COST_RT.getValue()) + parseFloat(edt_TRST_COM_COST_RT.getValue()) + parseFloat(edt_TRANSAGNT_COST_RT.getValue());
    pPF_TOT_FEE = pPF_TOT_FEE.toFixed(6);
    edt_PF_TOT_FEE.setValue(pPF_TOT_FEE);
    pTOT_COST_RT = parseFloat(pPF_TOT_FEE) + parseFloat(edt_MISC_COST_RT.getValue()) + parseFloat(edt_SYNTH_SWAP_COST_RT.getValue());
    pTOT_COST_RT = pTOT_COST_RT.toFixed(6);
    edt_TOT_COST_RT.setValue(pTOT_COST_RT);
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    await scwin.checkRt();
    let pPF_TOT_FEE = 0;
    let pTOT_COST_RT = 0;
    pPF_TOT_FEE = parseFloat(edt_CIS_COST_RT.getValue()) + parseFloat(edt_AP_CMP_LP_COST_RT.getValue()) + parseFloat(edt_TRST_COM_COST_RT.getValue()) + parseFloat(edt_TRANSAGNT_COST_RT.getValue());
    pPF_TOT_FEE = pPF_TOT_FEE.toFixed(6);
    pTOT_COST_RT = parseFloat(pPF_TOT_FEE) + parseFloat(edt_MISC_COST_RT.getValue()) + parseFloat(edt_SYNTH_SWAP_COST_RT.getValue());
    pTOT_COST_RT = pTOT_COST_RT.toFixed(6);
    if (edt_PF_TOT_FEE.getValue() !== pPF_TOT_FEE) {
        await $c.win.alert("입력한 보수값과 현재 '총보수'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }
    if (edt_TOT_COST_RT.getValue() !== pTOT_COST_RT) {
        await $c.win.alert("입력한 보수값과 현재 '총비용'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }
    if (txa_MISC_COST_DTL.getValue() !== "") {
        if (!$c.stf.checkMaxLength(txa_MISC_COST_DTL, 200, "기타비용 상세내역")) {
            txa_MISC_COST_DTL.focus();
            return false;
        }
    }
    if (txa_SYNTH_COST_DTL.getValue() !== "") {
        if (!$c.stf.checkMaxLength(txa_SYNTH_COST_DTL, 200, "스왑비용 상세내역")) {
            txa_SYNTH_COST_DTL.focus();
            return false;
        }
    }
    if (txb_HPAGE.getValue() === "") {
        await $c.win.alert("[홈페이지]를 입력하세요.");
        txb_HPAGE.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_HPAGE, 200, "홈페이지")) {
            txb_HPAGE.focus();
            return false;
        }
    }
    if (txb_TRST_CALC_PD_CONTN.getValue() === "") {
        await $c.win.alert("[회계기간]를 입력하세요.");
        txb_TRST_CALC_PD_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_TRST_CALC_PD_CONTN, 200, "회계기간")) {
            txb_TRST_CALC_PD_CONTN.focus();
            return false;
        }
    }
    if (txb_TRST_DISTR_PAY_BAS_DD_CONTN.getValue() === "") {
        await $c.win.alert("[분배금 지급기준일]를 입력하세요.");
        txb_TRST_DISTR_PAY_BAS_DD_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_TRST_DISTR_PAY_BAS_DD_CONTN, 300, "분배금 지급기준일")) {
            txb_TRST_DISTR_PAY_BAS_DD_CONTN.focus();
            return false;
        }
    }
    if (txa_PF_PROD_INFO.getValue() === "") {
        await $c.win.alert("[상품정보(기본정보)]를 입력하세요.");
        txa_PF_PROD_INFO.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txa_PF_PROD_INFO, 4000, "상품정보(기본정보)")) {
            txa_PF_PROD_INFO.focus();
            return false;
        }
    }
    if (txa_PF_INVSTWARN_CONTN.getValue() === "") {
        await $c.win.alert("[상품정보(투자유의사항)]를 입력하세요.");
        txa_PF_INVSTWARN_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txa_PF_INVSTWARN_CONTN, 4000, "상품정보(투자유의사항)")) {
            txa_PF_INVSTWARN_CONTN.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};
